import{i as e,r as t,s as n,t as r}from"./app-DuH0mZgh.js";var i=JSON.parse(`{"path":"/08-Player_Data_Storage_and_BI.html","title":"玩家数据存储方案：性能与 BI 的平衡之道 (Hybrid Storage Design)","lang":"en-US","frontmatter":{},"filePathRelative":"08-Player_Data_Storage_and_BI.md","git":{"createdTime":1765122408000,"updatedTime":1765122408000,"contributors":[{"name":"cuihairu","username":"cuihairu","email":"chuihairu@gmail.com","commits":1,"url":"https://github.com/cuihairu"}]}}`),a={name:`08-Player_Data_Storage_and_BI.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<h1 id="玩家数据存储方案-性能与-bi-的平衡之道-hybrid-storage-design" tabindex="-1"><a class="header-anchor" href="#玩家数据存储方案-性能与-bi-的平衡之道-hybrid-storage-design"><span>玩家数据存储方案：性能与 BI 的平衡之道 (Hybrid Storage Design)</span></a></h1><blockquote><p><strong>核心矛盾</strong>:</p><ul><li><strong>高性能 (Game)</strong>: 游戏逻辑喜欢对象化、结构紧凑的数据（如 C++ Struct / Protobuf），读写越快越好，最好一次 IO 搞定所有属性。</li><li><strong>便利性 (BI/Ops)</strong>: 运营和数据分析师喜欢关系型数据（SQL），希望所有属性都是独立的列，方便 <code>SELECT * FROM players WHERE level &gt; 50 AND gold &gt; 10000</code>。</li></ul></blockquote><p>为了同时满足这两个需求，专业架构推荐采用 <strong>&quot;关键字段列化 + 全量数据 Blob + 行为日志 TLog&quot;</strong> 的混合存储模式。</p><hr><h2 id="_1-数据库表结构设计-hybrid-schema" tabindex="-1"><a class="header-anchor" href="#_1-数据库表结构设计-hybrid-schema"><span>1. 数据库表结构设计 (Hybrid Schema)</span></a></h2><p>即使使用 MySQL，也不要把 200+ 个战斗属性设计成 200 个列。</p><h3 id="_1-1-核心表结构-t-character" tabindex="-1"><a class="header-anchor" href="#_1-1-核心表结构-t-character"><span>1.1 核心表结构 (<code>t_character</code>)</span></a></h3><div class="language-sql line-numbers-mode" data-highlighter="prismjs" data-ext="sql"><pre><code class="language-sql"><span class="line"><span class="token keyword">CREATE</span> <span class="token keyword">TABLE</span> <span class="token identifier"><span class="token punctuation">\`</span>t_character<span class="token punctuation">\`</span></span> <span class="token punctuation">(</span></span>
<span class="line">    <span class="token comment">-- 索引区：用于逻辑查找</span></span>
<span class="line">    <span class="token identifier"><span class="token punctuation">\`</span>char_id<span class="token punctuation">\`</span></span> <span class="token keyword">BIGINT</span> <span class="token operator">NOT</span> <span class="token boolean">NULL</span> <span class="token keyword">COMMENT</span> <span class="token string">&#39;角色ID&#39;</span><span class="token punctuation">,</span></span>
<span class="line">    <span class="token identifier"><span class="token punctuation">\`</span>account_id<span class="token punctuation">\`</span></span> <span class="token keyword">BIGINT</span> <span class="token operator">NOT</span> <span class="token boolean">NULL</span> <span class="token keyword">COMMENT</span> <span class="token string">&#39;账号ID&#39;</span><span class="token punctuation">,</span></span>
<span class="line"></span>
<span class="line">    <span class="token comment">-- 运营/BI 高频查询区 (Extracted Columns)</span></span>
<span class="line">    <span class="token comment">-- 这些字段在 Save 时，从内存从提取出来单独存列</span></span>
<span class="line">    <span class="token identifier"><span class="token punctuation">\`</span>name<span class="token punctuation">\`</span></span> <span class="token keyword">VARCHAR</span><span class="token punctuation">(</span><span class="token number">64</span><span class="token punctuation">)</span> <span class="token operator">NOT</span> <span class="token boolean">NULL</span> <span class="token keyword">COMMENT</span> <span class="token string">&#39;角色名&#39;</span><span class="token punctuation">,</span></span>
<span class="line">    <span class="token identifier"><span class="token punctuation">\`</span>level<span class="token punctuation">\`</span></span> <span class="token keyword">INT</span> <span class="token keyword">DEFAULT</span> <span class="token number">1</span> <span class="token keyword">COMMENT</span> <span class="token string">&#39;等级 (用于分布统计)&#39;</span><span class="token punctuation">,</span></span>
<span class="line">    <span class="token identifier"><span class="token punctuation">\`</span>vip_level<span class="token punctuation">\`</span></span> <span class="token keyword">INT</span> <span class="token keyword">DEFAULT</span> <span class="token number">0</span> <span class="token keyword">COMMENT</span> <span class="token string">&#39;VIP等级 (用于大R分析)&#39;</span><span class="token punctuation">,</span></span>
<span class="line">    <span class="token identifier"><span class="token punctuation">\`</span>power<span class="token punctuation">\`</span></span> <span class="token keyword">BIGINT</span> <span class="token keyword">DEFAULT</span> <span class="token number">0</span> <span class="token keyword">COMMENT</span> <span class="token string">&#39;战斗力 (用于实力分层)&#39;</span><span class="token punctuation">,</span></span>
<span class="line">    <span class="token identifier"><span class="token punctuation">\`</span>gold<span class="token punctuation">\`</span></span> <span class="token keyword">BIGINT</span> <span class="token keyword">DEFAULT</span> <span class="token number">0</span> <span class="token keyword">COMMENT</span> <span class="token string">&#39;金币 (经济监控)&#39;</span><span class="token punctuation">,</span></span>
<span class="line">    <span class="token identifier"><span class="token punctuation">\`</span>diamond<span class="token punctuation">\`</span></span> <span class="token keyword">BIGINT</span> <span class="token keyword">DEFAULT</span> <span class="token number">0</span> <span class="token keyword">COMMENT</span> <span class="token string">&#39;钻石 (核心存量)&#39;</span><span class="token punctuation">,</span></span>
<span class="line">    <span class="token identifier"><span class="token punctuation">\`</span>create_time<span class="token punctuation">\`</span></span> <span class="token keyword">DATETIME</span> <span class="token keyword">COMMENT</span> <span class="token string">&#39;创角时间 (留存分析)&#39;</span><span class="token punctuation">,</span></span>
<span class="line">    <span class="token identifier"><span class="token punctuation">\`</span>last_login<span class="token punctuation">\`</span></span> <span class="token keyword">DATETIME</span> <span class="token keyword">COMMENT</span> <span class="token string">&#39;最后登录 (流失分析)&#39;</span><span class="token punctuation">,</span></span>
<span class="line">    <span class="token identifier"><span class="token punctuation">\`</span>map_id<span class="token punctuation">\`</span></span> <span class="token keyword">INT</span> <span class="token keyword">DEFAULT</span> <span class="token number">0</span> <span class="token keyword">COMMENT</span> <span class="token string">&#39;所在地图 (卡点分析)&#39;</span><span class="token punctuation">,</span></span>
<span class="line"></span>
<span class="line">    <span class="token comment">-- 核心数据区 (Binary Blob)</span></span>
<span class="line">    <span class="token comment">-- 包含所有属性、Buff、技能CD、任务进度等海量细节</span></span>
<span class="line">    <span class="token comment">-- 游戏读写只认这个字段，高效且兼容性强 (Protobuf可扩展)</span></span>
<span class="line">    <span class="token identifier"><span class="token punctuation">\`</span>data_bin<span class="token punctuation">\`</span></span> <span class="token keyword">MEDIUMBLOB</span> <span class="token keyword">COMMENT</span> <span class="token string">&#39;Protobuf 序列化数据&#39;</span><span class="token punctuation">,</span></span>
<span class="line"></span>
<span class="line">    <span class="token keyword">PRIMARY</span> <span class="token keyword">KEY</span> <span class="token punctuation">(</span><span class="token identifier"><span class="token punctuation">\`</span>char_id<span class="token punctuation">\`</span></span><span class="token punctuation">)</span><span class="token punctuation">,</span></span>
<span class="line">    <span class="token keyword">INDEX</span> <span class="token identifier"><span class="token punctuation">\`</span>idx_acc<span class="token punctuation">\`</span></span> <span class="token punctuation">(</span><span class="token identifier"><span class="token punctuation">\`</span>account_id<span class="token punctuation">\`</span></span><span class="token punctuation">)</span><span class="token punctuation">,</span></span>
<span class="line">    <span class="token keyword">INDEX</span> <span class="token identifier"><span class="token punctuation">\`</span>idx_level_power<span class="token punctuation">\`</span></span> <span class="token punctuation">(</span><span class="token identifier"><span class="token punctuation">\`</span>level<span class="token punctuation">\`</span></span><span class="token punctuation">,</span> <span class="token identifier"><span class="token punctuation">\`</span>power<span class="token punctuation">\`</span></span><span class="token punctuation">)</span><span class="token punctuation">,</span> <span class="token comment">-- 方便运营后台查询</span></span>
<span class="line">    <span class="token keyword">INDEX</span> <span class="token identifier"><span class="token punctuation">\`</span>idx_last_login<span class="token punctuation">\`</span></span> <span class="token punctuation">(</span><span class="token identifier"><span class="token punctuation">\`</span>last_login<span class="token punctuation">\`</span></span><span class="token punctuation">)</span>      <span class="token comment">-- 方便找流失用户</span></span>
<span class="line"><span class="token punctuation">)</span> <span class="token keyword">ENGINE</span><span class="token operator">=</span><span class="token keyword">InnoDB</span> <span class="token keyword">DEFAULT</span> <span class="token keyword">CHARSET</span><span class="token operator">=</span>utf8mb4<span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_1-2-为什么这样设计" tabindex="-1"><a class="header-anchor" href="#_1-2-为什么这样设计"><span>1.2 为什么这样设计？</span></a></h3><ol><li><strong>性能极高</strong>: <code>data_bin</code> 是一坨二进制，游戏服务器 Deserialize 极快。新增一个“火抗性”属性，<strong>不需要</strong> <code>ALTER TABLE</code>，直接改 Protobuf 定义即可，DB 无感知。</li><li><strong>满足 80% 的 BI 需求</strong>: 运营通常只关心等级分布、大 R 流失、货币通胀。这些关键数据做成了列 (<code>level</code>, <code>gold</code>)，可以直接 SQL 查询，速度飞快。</li><li><strong>满足 100% 的游戏逻辑</strong>: 无论多复杂的嵌套结构（如 <code>List&lt;Item&gt;</code>），都可以塞进 Blob。</li></ol><hr><h2 id="_2-属性的序列化存储-protobuf-design" tabindex="-1"><a class="header-anchor" href="#_2-属性的序列化存储-protobuf-design"><span>2. 属性的序列化存储 (Protobuf Design)</span></a></h2><p>在 <code>data_bin</code> 内部，建议使用 Protobuf 的 <code>map</code> 特性来存储属性，以兼顾灵活性和存储空间（稀疏存储）。</p><div class="language-protobuf line-numbers-mode" data-highlighter="prismjs" data-ext="protobuf"><pre><code class="language-protobuf"><span class="line"><span class="token keyword">message</span> <span class="token class-name">PlayerProfile</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token comment">// 基础信息</span></span>
<span class="line">    <span class="token builtin">uint64</span> id <span class="token operator">=</span> <span class="token number">1</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token builtin">string</span> name <span class="token operator">=</span> <span class="token number">2</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line">    <span class="token comment">// 属性模块 (核心设计)</span></span>
<span class="line">    <span class="token comment">// key: 属性ID (Define in C++ enum/Excel)</span></span>
<span class="line">    <span class="token comment">// value: 属性值</span></span>
<span class="line">    <span class="token comment">// 优势: 只有非0的属性才占用空间。如果是 500 个属性但玩家只有 3 个有值，则只存 3 个。</span></span>
<span class="line">    <span class="token map class-name">map<span class="token punctuation">&lt;</span><span class="token builtin">int32</span><span class="token punctuation">,</span> <span class="token builtin">int64</span><span class="token punctuation">&gt;</span></span> attributes <span class="token operator">=</span> <span class="token number">10</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line">    <span class="token comment">// 模块化数据</span></span>
<span class="line">    <span class="token positional-class-name class-name">BagData</span> bag <span class="token operator">=</span> <span class="token number">11</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token positional-class-name class-name">QuestData</span> quest <span class="token operator">=</span> <span class="token number">12</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token positional-class-name class-name">SkillData</span> skill <span class="token operator">=</span> <span class="token number">13</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>BI 如何分析 <code>data_bin</code> 里的冷门数据？</strong></p><ul><li><strong>离线 ETL</strong>: 写一个简单的 Python/Go 工具，每天晚上把从库的 <code>t_character</code> 导出，解析 Protobuf Blob，展平为 Hive/ClickHouse 的大宽表。</li></ul><hr><h2 id="_3-真正的-bi-核心-tlog-transaction-log" tabindex="-1"><a class="header-anchor" href="#_3-真正的-bi-核心-tlog-transaction-log"><span>3. 真正的 BI 核心：TLog (Transaction Log)</span></a></h2><p><strong>千万不要试图通过查询数据库快照来做精细的 BI 分析。</strong> 数据库存的是<strong>当前状态 (Snapshot)</strong>，BI 需要的是<strong>变化过程 (Flow)</strong>。</p><ul><li><strong>例子</strong>: 玩家只有 100 金币。 <ul><li><strong>DB 状态</strong>: <code>gold = 100</code>。</li><li><strong>BI 问题</strong>: 这 100 是充值来的？还是打怪掉的一点点攒的？还是昨天有 100 万 今天花剩下的？</li><li><strong>结论</strong>: DB 回答不了这个问题。</li></ul></li></ul><h3 id="_3-1-埋点日志系统设计" tabindex="-1"><a class="header-anchor" href="#_3-1-埋点日志系统设计"><span>3.1 埋点日志系统设计</span></a></h3><p>你需要一套 <strong>LogServer</strong>。GameServer 不写 DB 日志，而是发类似于 <code>UDP/TCP</code> 的日志包给 LogServer，由 LogServer 落盘为文件，然后由 Flume/Filebeat 采集到大数据平台。</p><p><strong>日志格式标准 (TLog 标准)</strong>:</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">时间 | 平台 | 区服 | 玩家ID | 事件名 | 变化量 | 变化后存量 | 动作原因 | 关联对象</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p><strong>示例日志</strong>:</p><ol><li><strong>MoneyFlow (货币流水)</strong>: <code>2024-12-06 10:00:01 | Android | S1 | 10086 | AddGold | +500 | 1500 | KillBoss | BossID:9981</code></li><li><strong>ItemFlow (道具流水)</strong>: <code>2024-12-06 10:05:30 | Android | S1 | 10086 | DelItem | -1 | 0 | Consume | ItemID:HP_Potion</code></li><li><strong>LevelFlow (升级流水)</strong>: <code>2024-12-06 11:20:00 | Android | S1 | 10086 | LevelUp | 10-&gt;11 | 11 | ExpFull | NULL</code></li></ol><h3 id="_3-2-bi-架构图" tabindex="-1"><a class="header-anchor" href="#_3-2-bi-架构图"><span>3.2 BI 架构图</span></a></h3><div class="language-mermaid line-numbers-mode" data-highlighter="prismjs" data-ext="mermaid"><pre><code class="language-mermaid"><span class="line"><span class="token keyword">graph</span> LR</span>
<span class="line">    GS<span class="token text string">[GameServer]</span> <span class="token arrow operator">--&gt;</span> <span class="token label property">|Log Packet|</span> LogAgent<span class="token text string">[LogServer/Agent]</span></span>
<span class="line">    LogAgent <span class="token arrow operator">--&gt;</span> <span class="token label property">|Write|</span> LocalFile<span class="token text string">[本地日志文件]</span></span>
<span class="line">    LocalFile <span class="token arrow operator">--&gt;</span> <span class="token label property">|Filebeat|</span> Kafka<span class="token text string">[Kafka 消息队列]</span></span>
<span class="line"></span>
<span class="line">    Kafka <span class="token arrow operator">--&gt;</span> <span class="token label property">|Realtime|</span> Flink[实时计算 <span class="token text string">(GM监控/在线人数)]</span></span>
<span class="line">    Kafka <span class="token arrow operator">--&gt;</span> <span class="token label property">|Offline|</span> HDFS/S3[数据仓库 <span class="token text string">(Hive/ClickHouse)]</span></span>
<span class="line"></span>
<span class="line">    <span class="token keyword">subgraph</span> DataWarehouse</span>
<span class="line">        ODS<span class="token text string">[原始层]</span> <span class="token arrow operator">--&gt;</span> DWD<span class="token text string">[明细层]</span></span>
<span class="line">        DWD <span class="token arrow operator">--&gt;</span> DWS<span class="token text string">[汇总层: 留存/LTV/ARPU]</span></span>
<span class="line">    <span class="token keyword">end</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><hr><h2 id="_4-总结" tabindex="-1"><a class="header-anchor" href="#_4-总结"><span>4. 总结</span></a></h2><p><strong>“既要性能，又要 BI” 的最终解决方案：</strong></p><ol><li><strong>运行时 (Game)</strong>: 使用 <code>C++ Object</code>，极致速度。</li><li><strong>持久化 (DB)</strong>: 使用 <strong>Hybrid 模式</strong>。 <ul><li><strong>Blob</strong>: 存全量，保证不丢数据，开发方便。</li><li><strong>Columns</strong>: 存 10-20 个核心维度 (等级/金钱/战力)，方便后台管理和简单统计。</li></ul></li><li><strong>深度分析 (BI)</strong>: 使用 <strong>TLog 流水日志</strong>。 <ul><li>不要指望 DB 能分析出“玩家行为习惯”。</li><li>全靠埋点日志导入 ClickHouse/Doris 进行多维分析。</li></ul></li></ol><p>这种架构是腾讯、网易等大厂的标准做法，兼顾了服务器的 TPS 和 数据分析的深度。</p>`,33)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};